const respuesta = $json || {};
const codigo = Number(respuesta.statusCode || 0);
const datos = respuesta.body && typeof respuesta.body === 'object' ? respuesta.body : {};
const problemas = [];
if (respuesta.error || !codigo) problemas.push('No se pudo conectar al servicio');
else if (codigo < 200 || codigo >= 300) problemas.push('HTTP ' + codigo);
if (!datos || typeof datos.estado !== 'string') problemas.push('Contrato de estado no válido: falta estado');
else if (datos.estado !== 'ok') problemas.push('Estado: ' + datos.estado);
if (datos.pendientes !== undefined) {
  const pendientes = Number(datos.pendientes);
  if (!Number.isFinite(pendientes) || pendientes < 0) problemas.push('Campo pendientes inválido');
  else if (pendientes > 20) problemas.push('Hay ' + pendientes + ' casos pendientes (umbral: 20)');
}
return [{json:{alerta:problemas.length>0,motivo:problemas.join(' · ') || 'sin incidencias',revisado:new Date().toISOString()} }];

